  const { scene } = useGLTF('https://cdn.3dassets.dev/assets/28553/v1/model.glb')
  return <primitive object={scene} {...props} />
}
useGLTF.preload('https://cdn.3dassets.dev/assets/28553/v1/model.glb')

usage.unity:
// Unity: import model.glb with glTFast (Package Manager: com.unity.cloud.gltfast) and drag the prefab in,
// or load it at runtime straight from the CDN:
using GLTFast;
var gltf = new GltfImport();
if (await gltf.Load("https://cdn.3dassets.dev/assets/28553/v1/model.glb")) await gltf.InstantiateMainSceneAsync(transform);
